package com.hartens.optimizer;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.util.concurrent.*;
public final class MainActivity extends Activity {
 private EditText ip;private TextView result;private LinearLayout root;private ExecutorService worker=Executors.newSingleThreadExecutor();private SharedPreferences pref;
 interface Job {String run(AdbClient a)throws Exception;}
 public void onCreate(Bundle state){super.onCreate(state);pref=getSharedPreferences("settings",0);ScrollView sc=new ScrollView(this);root=new LinearLayout(this);root.setPadding(24,28,24,32);root.setOrientation(1);sc.addView(root);setContentView(sc);title("HARTENS OPTIMIZER");paragraph("Hartens HTY-43F06B-VZ · Управление через ADB по Wi-Fi без Termux. Выключи VPN на телефоне. Bluetooth и системные службы не отключаются.");ip=new EditText(this);ip.setSingleLine(true);ip.setText(pref.getString("ip","192.168.1.38"));ip.setHint("IP телевизора");root.addView(ip);button("Проверить подключение и память",a->"Модель: "+a.shell("getprop ro.product.model")+"\nAndroid: "+a.shell("getprop ro.build.version.release")+"\n"+a.shell("df -h /data"));button("Анимации 0.5x",a->{String[] keys={"window_animation_scale","transition_animation_scale","animator_duration_scale"};for(String k:keys){if(!pref.contains("before_"+k))pref.edit().putString("before_"+k,a.shell("settings get global "+k)).commit();a.shell("settings put global "+k+" 0.5");}return "Анимации 0.5x установлены";});button("Восстановить анимации",a->{int n=0;for(String k:new String[]{"window_animation_scale","transition_animation_scale","animator_duration_scale"}){String v=pref.getString("before_"+k,null);if(v==null)continue;if("null".equals(v))a.shell("settings delete global "+k);else if(v.matches("[0-9]+(\\.[0-9]+)?"))a.shell("settings put global "+k+" "+v);else continue;pref.edit().remove("before_"+k).commit();n++;}return "Восстановлено: "+n;});button("Очистить временный кэш",a->{String before=a.shell("df -h /data");a.shell("pm trim-caches 600M");return "До:\n"+before+"\nПосле:\n"+a.shell("df -h /data");});paragraph("Приложения (отключение обратимо). Уже отключённые пакеты оставляем без изменений.");app("Яндекс Игры","ru.yandex.games");app("Отчёты об ошибках","com.yandex.tv.bugreportsender");button("Посмотреть отключённые приложения",a->a.shell("pm list packages -d"));result=new TextView(this);result.setPadding(10,18,10,18);result.setTextIsSelectable(true);result.setText("Нажми «Проверить подключение». При первом подключении разреши ADB на экране телевизора.");root.addView(result);paragraph("После работы выключай ADB Mode в сервисном меню ТВ. Рекламу YouTube и весь контент YaOS приложение не удаляет.");}
 private void app(String name,String pkg){button("Отключить: "+name,a->{String disabled=a.shell("pm list packages -d");if(disabled.contains("package:"+pkg))return "Уже отключено";a.shell("pm disable-user --user 0 "+pkg);return a.shell("pm list packages -d").contains("package:"+pkg)?"Отключено: "+name:"Не удалось подтвердить изменение";});button("Восстановить: "+name,a->{a.shell("pm enable --user 0 "+pkg);return "Команда включения отправлена: "+name;});}
 private void title(String t){TextView v=new TextView(this);v.setText(t);v.setTextSize(24);v.setTextColor(Color.rgb(50,40,175));v.setPadding(0,4,0,18);root.addView(v);}
 private void paragraph(String t){TextView v=new TextView(this);v.setText(t);v.setTextSize(14);v.setPadding(0,10,0,15);root.addView(v);}
 private void button(String text,Job job){Button b=new Button(this);b.setText(text);b.setAllCaps(false);root.addView(b);b.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(text).setMessage("Выполнить действие на телевизоре?").setNegativeButton("Отмена",(d,w)->{}).setPositiveButton("Выполнить",(d,w)->run(job)).show());}
 private void run(Job job){String host=ip.getText().toString().trim();pref.edit().putString("ip",host).apply();result.setText("Подключение...");worker.execute(()->{String msg;try(AdbClient a=new AdbClient(this)){a.connect(host);msg=job.run(a);}catch(Exception e){msg="Ошибка: "+e.getMessage()+"\nПроверь VPN, ADB Mode и IP телевизора.";}String m=msg;runOnUiThread(()->result.setText(m));});}
 protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}